public class OrdersModel : PageModel
{
    private readonly IOrderService _orders;
    public OrdersModel(IOrderService orders) => _orders = orders;
    public IReadOnlyList<Order> Orders { get; private set; } = [];
    public void OnGet() => Orders = _orders.ForUser(User.Identity!.Name!);  // domain
    public IActionResult OnPost(OrderInput input)
    {
        if (!ModelState.IsValid) return Page();
        _orders.Place(input); return RedirectToPage("Orders");  // POST-redirect-GET
    }
}
// Pages/Orders.cshtml: @page -> GET/POST /Orders, no controller
